import test from 'node:test';import assert from 'node:assert/strict';import {createSimulationPacer} from '../tools/trees/prototype_simulation_pacer.mjs';
test('requests only due work, one at a time, and preserves backlog without frame budgets',()=>{
 const p=createSimulationPacer('s',{stepSeconds:.05,maxBacklogSteps:2});assert.equal(p.request(0).reason,'not-due');assert.equal(p.request(49).reason,'not-due');const a=p.request(50);assert.equal(a.accepted,true);assert.equal(p.request(100).reason,'busy');assert.equal(p.acknowledge({session:'old',sequence:a.sequence,completed:true}).reason,'stale');assert.equal(p.acknowledge({session:'s',sequence:a.sequence,completed:true,simulationTime:.05}).accepted,true);const state=p.inspect(300);assert.equal(state.completed,1);assert.equal(state.backlogSteps,5);assert.equal(state.overloaded,true);for(let i=0;i<5;i++){const b=p.request(300);assert.equal(b.accepted,true);p.acknowledge({session:'s',sequence:b.sequence,completed:true,simulationTime:(i+2)*.05});}assert.equal(p.request(300).reason,'not-due');
});
test('pause excludes elapsed time, permits completion of an in-flight step and changes speed without rewinding',()=>{
 const p=createSimulationPacer('s',{stepSeconds:.1});p.inspect(0);const a=p.request(100);p.pause(120);assert.equal(p.request(600).reason,'paused');assert.equal(p.acknowledge({session:'s',sequence:a.sequence,completed:true,simulationTime:.1}).accepted,true);assert.equal(p.inspect(1100).targetSteps,1.2);p.setRate(1100,2);p.resume(1500);assert.equal(p.request(1539).reason,'not-due');const b=p.request(1540);assert.equal(b.accepted,true);p.acknowledge({session:'s',sequence:b.sequence,completed:true,simulationTime:.2});assert.equal(p.inspect(1540).completed,2);
});
test('rejects invalid clocks and does not admit stale or duplicate acknowledgements',()=>{
 const p=createSimulationPacer('s');assert.equal(p.acknowledge({session:'s',sequence:null,completed:true}).reason,'stale');p.inspect(100);assert.throws(()=>p.inspect(99),RangeError);assert.throws(()=>p.setRate(100,17),RangeError);const a=p.request(200);assert.equal(p.acknowledge({session:'s',sequence:a.sequence,completed:true,simulationTime:1/60}).accepted,true);assert.equal(p.acknowledge({session:'s',sequence:a.sequence,completed:true}).reason,'stale');assert.equal(p.inspect(200).completed,1);
});

test('non-advancing or unexpected authoritative time closes the pacer',()=>{const p=createSimulationPacer('s',{initialTime:10,stepSeconds:.1});p.inspect(0);const req=p.request(100);assert.equal(p.acknowledge({session:'s',sequence:req.sequence,completed:true,simulationTime:10}).reason,'time');assert.equal(p.request(200).reason,'fault');assert.deepEqual(p.inspect(200),{fault:true});});
